commands.command:
sudo tee /etc/nginx/conf.d/rotating-tls.conf > /dev/null <<'EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name node1.cert-rotation.local;

    ssl_certificate     /etc/pki/tls/rotating/tls.crt;
    ssl_certificate_key /etc/pki/tls/rotating/tls.key;

    location / {
        return 200 "ok\n";
        add_header Content-Type text/plain;
    }
}
EOF
sudo nginx -t 2>&1
